const isDlcCampaign = factCampaign === 'dlc_genderbend_hachiman' || factCampaign === 'dlc_body_swap_mrs_yukinoshita';
const effectiveScene = isDlcCampaign ? 118 : factScene;
const facts = [];
if (effectiveScene >= 11) facts.push('拉芙希妮已保存林间学校获得的蒲公英种子。');
if (effectiveScene >= 25) facts.push('结衣送给拉芙希妮的发卡已经实际存在；此前不得倒推。');
if (effectiveScene >= 45) facts.push('红丝带已由雪乃在发生过的互动中系到拉芙希妮左腕；此前只有烧焦丝带。');
if (effectiveScene >= 49) facts.push('一色彩羽已经登场；此前不得让核心角色提前认识她。');
if (effectiveScene >= 53) facts.push('一色彩羽已经当选学生会长。');
if (effectiveScene >= 91) facts.push('平冢静已经调离总武高中；此前不得把调离当作完成事实。');
if (effectiveScene >= 99) facts.push('拉芙希妮已将五件重要物品整理为可见的个人珍藏。');
